// Loading of the dataset (Dataverse release layout) and the episode list.
//
//   <data>/images/<work>/<work>__NN.jpg      step images (NN starts at 01)
//   <data>/texts/<work>.csv (or .tab)        imageName, caption_en
//   <data>/display/<work>/...                display images + coordinate_manifest.json
//                                            (generated by tools/normalize_coordinates.py)
//
// The caption on the row of image NN describes the operation from state NN to
// state NN+1. Works are matched to episodes by the numeric ID prefix of the
// folder name (e.g. "001" in "001_Long-Horned_Samurai_Helmet").

import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp"]);

export async function loadEpisodes(episodesPath) {
  const rows = parseDelimited(await readFile(episodesPath, "utf8"), ",");
  const [header, ...body] = rows;
  const column = (name) => header.indexOf(name);
  return body
    .filter((row) => row.length >= header.length)
    .map((row) => ({
      id: row[column("id")],
      designName: row[column("design_name")],
      startImage: Number(row[column("start_image")]),
      targetImage: Number(row[column("target_image")]),
    }));
}

export async function loadWorks(dataDirectory) {
  const imagesRoot = path.join(dataDirectory, "images");
  let folders;
  try {
    folders = (await readdir(imagesRoot, { withFileTypes: true }))
      .filter((entry) => entry.isDirectory())
      .map((entry) => entry.name)
      .sort();
  } catch {
    throw new Error(`No images/ directory found in ${dataDirectory}`);
  }

  const works = new Map();
  for (const folder of folders) {
    const id = folder.match(/^(\d+)/)?.[1];
    if (!id) continue;
    const images = await listImages(path.join(imagesRoot, folder));
    if (!images.length) continue;
    works.set(id.padStart(3, "0"), {
      id: id.padStart(3, "0"),
      folder,
      images, // images[n - 1] is the file name of state n
      captions: await loadCaptions(dataDirectory, folder, images),
      frames: await loadCoordinateFrames(dataDirectory, folder),
    });
  }
  return works;
}

async function listImages(directory) {
  const names = (await readdir(directory)).filter((name) =>
    IMAGE_EXTENSIONS.has(path.extname(name).toLowerCase()),
  );
  const byNumber = new Map();
  for (const name of names) {
    const number = Number(name.match(/(\d+)\.[^.]+$/)?.[1]);
    if (number > 0) byNumber.set(number, name);
  }
  const count = Math.max(0, ...byNumber.keys());
  return Array.from({ length: count }, (_, index) => byNumber.get(index + 1) || null);
}

async function loadCaptions(dataDirectory, folder, images) {
  for (const [extension, delimiter] of [[".csv", ","], [".tab", "\t"], [".tsv", "\t"]]) {
    let text;
    try {
      text = await readFile(path.join(dataDirectory, "texts", folder + extension), "utf8");
    } catch {
      continue;
    }
    const rows = parseDelimited(text, delimiter);
    const header = rows.findIndex((row) => row.includes("imageName") && row.includes("caption_en"));
    if (header < 0) continue;
    const imageColumn = rows[header].indexOf("imageName");
    const captionColumn = rows[header].indexOf("caption_en");
    const captions = images.map(() => "");
    for (const row of rows.slice(header + 1)) {
      const number = Number(row[imageColumn]?.match(/(\d+)\.[^.]+$/)?.[1]);
      if (number >= 1 && number <= images.length) {
        captions[number - 1] = row[captionColumn]?.trim() || "";
      }
    }
    return captions; // captions[n - 1]: operation from state n to state n + 1
  }
  throw new Error(`No caption file found for ${folder} in ${path.join(dataDirectory, "texts")}`);
}

async function loadCoordinateFrames(dataDirectory, folder) {
  const frames = new Map();
  try {
    const manifest = JSON.parse(
      await readFile(
        path.join(dataDirectory, "display", folder, "coordinate_manifest.json"),
        "utf8",
      ),
    );
    for (const record of manifest.images || []) {
      if (record.status !== "generated") continue;
      const ratioX = record.output_size.width / record.canvas_size.width;
      const ratioY = record.output_size.height / record.canvas_size.height;
      // Maps a normalized point (x, y) to display-image pixels:
      //   px = originX + x * scaleX,  py = originY - y * scaleY
      frames.set(record.image, {
        width: record.output_size.width,
        height: record.output_size.height,
        originX: record.centroid_px.x * ratioX,
        originY: record.centroid_px.y * ratioY,
        scaleX: record.scale_px_per_normalized_unit * ratioX,
        scaleY: record.scale_px_per_normalized_unit * ratioY,
      });
    }
  } catch {
    // No display images: the UI shows the original images without markers.
  }
  return frames;
}

// Minimal RFC 4180-style parser (quoted fields, escaped quotes, CRLF).
export function parseDelimited(text, delimiter) {
  const rows = [];
  let row = [];
  let field = "";
  let quoted = false;
  const source = text.replace(/^﻿/, "");
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    if (quoted) {
      if (char === '"' && source[index + 1] === '"') {
        field += '"';
        index += 1;
      } else if (char === '"') {
        quoted = false;
      } else {
        field += char;
      }
    } else if (char === '"') {
      quoted = true;
    } else if (char === delimiter) {
      row.push(field);
      field = "";
    } else if (char === "\n" || char === "\r") {
      if (char === "\r" && source[index + 1] === "\n") index += 1;
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else {
      field += char;
    }
  }
  if (field || row.length) {
    row.push(field);
    rows.push(row);
  }
  return rows.filter((cells) => cells.some((cell) => cell !== ""));
}
